using Aspire.Hosting.Testing;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Evaluation harness that starts the AppHost and runs scenarios against it.
/// </summary>
public class EvaluationTests
{
    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        await app.WaitForHealthyAsync();
    }

    [Fact]
    public async Task AppHost_ResourcesAreRunning()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();

        var resourceNotificationService = app.Services
            .GetRequiredService<ResourceNotificationService>();

        // Verify all resources reach a running state within timeout.
        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(60));
        await foreach (var evt in resourceNotificationService
            .WatchAsync(cts.Token))
        {
            if (evt.Snapshot.State?.Text == "Running")
                break;
        }
    }

    [Fact]
    public async Task EvaluationConfig_LoadsSuccessfully()
    {
        var configPath = Path.Combine(AppContext.BaseDirectory, "evaluation.yml");
        Assert.True(File.Exists(configPath), "evaluation.yml must be present in output.");

        var content = await File.ReadAllTextAsync(configPath);
        Assert.Contains("scenarios:", content);
    }
}

